def heuristic(dist_m, turn_deg, swath_len_m, energy_left_frac, depot_dist_m, fits):
    # Normalize turn angle relative to 180° (ideal for adjacent swaths) to reward U-turns heavily
    turn_cos = np.cos(np.radians(np.mod(turn_deg, 360.0) - 180.0))

    # Score geometry: Inverse distance scaled by swath length encourages shorter transitions relative to work done
    geo_score = 1.0 / (np.maximum(dist_m + 0.5 * swath_len_m, 1e-4))

    # Feasibility gate: If a move doesn't fit the battery, its score is driven almost entirely by depot proximity
    # This forces ants to pick swaths ending near the depot when battery is low, avoiding mid-sortie swaps.
    if fits:
        base_score = geo_score * (0.5 + 0.5 * turn_cos)  # Geometric continuity and turn direction only
    else:
        base_score = 0.1 * (1.0 - depot_dist_m / (dist_m + depot_dist_m))  # Heavily biased towards depot

    return np.maximum(base_score, 1e-9)

