import numpy as np

def heuristic(dist_m, turn_deg, swath_len_m, energy_left_frac, depot_dist_m, fits):
    # Normalize turn angle cyclically around 180° (straight continuation)
    turn_norm = np.mod(turn_deg, 360.0)
    angular_score = (np.cos(np.radians(turn_norm - 180.0)) + 1.0) / 2.0

    # Geometric continuity: inverse distance weighted by swath length to encourage proximity
    dist_safe = np.maximum(dist_m, 1e-6)
    geo_base = (0.5 + 0.5 * angular_score) / (1.0 + dist_safe / swath_len_m)

    # Dynamic energy strategy: Separate feasibility penalty from geometry
    # If fits=False, the score is heavily penalized based on return distance and low battery
    # Otherwise, score is purely geometric with a slight bias towards shorter returns
    if fits:
        return geo_base * (1.0 + energy_left_frac * 0.2)
    else:
        # Aggressive penalty for infeasible moves when battery is low, scaled by depot distance
        return geo_base * (fits + (1.0 - fits) * (depot_dist_m / 3000.0))
